package com.bookingSeatApplication.demo;
import java.time.*;
import org.h2.jdbcx.JdbcDataSource;
import org.junit.jupiter.api.Test;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.DataSourceTransactionManager;
import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;
import org.springframework.transaction.support.TransactionTemplate;
import static org.junit.jupiter.api.Assertions.*;
class DemoDataInitializerTest {
    @Test void seedsTimetableAndOccupancyAndRerunsWithoutOverwriting() {
        JdbcDataSource ds=new JdbcDataSource();ds.setURL("jdbc:h2:mem:seed;MODE=MySQL;DB_CLOSE_DELAY=-1");
        JdbcTemplate db=new JdbcTemplate(ds);
        String schema="""
        CREATE TABLE admin_users(admin_id INT AUTO_INCREMENT PRIMARY KEY, username VARCHAR(100) UNIQUE, password VARCHAR(255));
        CREATE TABLE routes(route_id INT AUTO_INCREMENT PRIMARY KEY, source VARCHAR(100), destination VARCHAR(100), UNIQUE(source,destination));
        CREATE TABLE buses(bus_id INT AUTO_INCREMENT PRIMARY KEY, route_id INT, travel_date DATE, travel_time TIME, total_seats INT);
        CREATE TABLE seats(seat_id INT AUTO_INCREMENT PRIMARY KEY, bus_id INT, seat_number VARCHAR(20), is_booked BOOLEAN, UNIQUE(bus_id,seat_number));
        CREATE TABLE passengers(passenger_id INT AUTO_INCREMENT PRIMARY KEY, passenger_name VARCHAR(150), email VARCHAR(190) UNIQUE, phone_number VARCHAR(40), password VARCHAR(255));
        CREATE TABLE schedules(schedule_id INT AUTO_INCREMENT PRIMARY KEY, route_id INT, bus_id INT, travel_date DATE, departure_time TIME, price DECIMAL(10,2));
        CREATE TABLE bookings(booking_id INT AUTO_INCREMENT PRIMARY KEY,schedule_id INT,seat_id INT,passenger_id INT,passenger_name VARCHAR(150),phone_number VARCHAR(40),booking_reference VARCHAR(40) UNIQUE,booking_status VARCHAR(20),amount DECIMAL(10,2),active_seat_id INT GENERATED ALWAYS AS (CASE WHEN booking_status='CANCELLED' THEN NULL ELSE seat_id END),UNIQUE(schedule_id,active_seat_id));
        CREATE TABLE demo_seed_state(seed_key VARCHAR(80) PRIMARY KEY);
        CREATE TABLE demo_bus_slots(route_id INT,slot INT,bus_id INT UNIQUE,PRIMARY KEY(route_id,slot));
        CREATE TABLE demo_schedules(schedule_id INT PRIMARY KEY);
        CREATE TABLE owner_users(owner_id INT AUTO_INCREMENT PRIMARY KEY,username VARCHAR(60) UNIQUE,full_name VARCHAR(150),phone_number VARCHAR(40),password VARCHAR(255),active BOOLEAN,approval_status VARCHAR(20),verification_details VARCHAR(1000),reviewed_by INT,reviewed_at TIMESTAMP,review_note VARCHAR(500));
        CREATE TABLE bus_owners(bus_id INT PRIMARY KEY,owner_id INT REFERENCES owner_users(owner_id));
        CREATE TABLE owner_approval_audit(audit_id BIGINT AUTO_INCREMENT PRIMARY KEY,owner_id INT REFERENCES owner_users(owner_id),admin_id INT REFERENCES admin_users(admin_id),decision VARCHAR(20),reason VARCHAR(500),reviewed_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
        INSERT INTO demo_seed_state VALUES('lock');
        """;
        for(String sql:schema.split(";")) if(!sql.isBlank()) db.execute(sql);
        var encoder=new BCryptPasswordEncoder(4);
        var tx=new TransactionTemplate(new DataSourceTransactionManager(ds));
        Clock clock=Clock.fixed(Instant.parse("2026-10-21T02:30:00Z"),ZoneId.of("Asia/Colombo"));
        var seeder=new DemoDataInitializer(db,encoder,tx,clock,14,"uvin","test-admin-password","test-passenger-password","test-owner-password");
        seeder.refresh();
        assertEquals(20,db.queryForObject("SELECT COUNT(*) FROM routes",Integer.class));
        assertEquals(160,db.queryForObject("SELECT COUNT(*) FROM buses",Integer.class));
        assertEquals(2240,db.queryForObject("SELECT COUNT(*) FROM schedules",Integer.class));
        assertEquals(6400,db.queryForObject("SELECT COUNT(*) FROM seats",Integer.class));
        assertEquals(0,db.queryForObject("SELECT COUNT(*) FROM (SELECT route_id,travel_date,COUNT(*) AS n,COUNT(DISTINCT departure_time) AS t FROM schedules GROUP BY route_id,travel_date HAVING n<>8 OR t<>8) x",Integer.class));
        assertEquals(0,db.queryForObject("SELECT COUNT(*) FROM (SELECT schedule_id,COUNT(*) AS n,COUNT(DISTINCT passenger_id) AS p FROM bookings GROUP BY schedule_id HAVING n<8 OR n>10 OR n<>p) x",Integer.class));
        assertTrue(encoder.matches("test-admin-password",db.queryForObject("SELECT password FROM admin_users WHERE username='uvin'",String.class)));
        assertTrue(encoder.matches("test-passenger-password",db.queryForObject("SELECT password FROM passengers ORDER BY passenger_id LIMIT 1",String.class)));
        assertEquals(3,db.queryForObject("SELECT COUNT(*) FROM owner_users WHERE approval_status='PENDING'",Integer.class));
        assertEquals(2,db.queryForObject("SELECT COUNT(*) FROM owner_users WHERE approval_status='APPROVED'",Integer.class));
        assertEquals(6,db.queryForObject("SELECT COUNT(*) FROM bus_owners",Integer.class));
        assertEquals(2,db.queryForObject("SELECT COUNT(*) FROM owner_approval_audit WHERE reason LIKE 'DEMO ONLY:%'",Integer.class));
        assertEquals(0,db.queryForObject("SELECT COUNT(*) FROM owner_users WHERE approval_status='PENDING' AND (reviewed_by IS NOT NULL OR reviewed_at IS NOT NULL)",Integer.class));
        assertTrue(encoder.matches("test-owner-password",db.queryForObject("SELECT password FROM owner_users WHERE username='demo_owner_kandy'",String.class)));
        db.update("UPDATE owner_users SET approval_status='REJECTED',active=FALSE,password='changed' WHERE username='demo_owner_ella'");
        db.update("DELETE FROM bus_owners WHERE owner_id=(SELECT owner_id FROM owner_users WHERE username='demo_owner_ella')");
        var seatDao=new com.bookingSeatApplication.dao.impl.SeatDaoImpl();
        org.springframework.test.util.ReflectionTestUtils.setField(seatDao,"jdbcTemplate",db);
        assertEquals(40,seatDao.getSeatsByBus(1).size());
        long occupied=seatDao.getSeatsForSchedule(1).stream().filter(s -> Boolean.TRUE.equals(s.getBooked())).count();
        assertTrue(occupied>=8 && occupied<=10);
        var scheduleDao=new com.bookingSeatApplication.dao.impl.ScheduleDaoImpl();
        org.springframework.test.util.ReflectionTestUtils.setField(scheduleDao,"jdbcTemplate",db);
        var trips=scheduleDao.search("Colombo","Kandy",LocalDate.of(2026,10,21));
        assertEquals(8,trips.size());
        assertTrue(trips.stream().allMatch(t->t.getTotalSeats()==40 && t.getAvailableSeats()>=30 && t.getAvailableSeats()<=32));
        var bookingDao=new com.bookingSeatApplication.dao.impl.BookingDaoImpl();
        org.springframework.test.util.ReflectionTestUtils.setField(bookingDao,"jdbcTemplate",db);
        var realBooking=new com.bookingSeatApplication.model.Booking();
        realBooking.setScheduleId(1);realBooking.setSeatId(40);realBooking.setPassengerId(1);
        realBooking.setPassengerName("New passenger reservation");realBooking.setPhoneNumber("0771234567");
        realBooking.setBookingStatus(com.bookingSeatApplication.model.BookingStatus.PENDING_PAYMENT);
        realBooking.setAmount(new java.math.BigDecimal("1200"));
        int bookingId=bookingDao.saveBooking(realBooking);
        bookingDao.updateBookingReference(bookingId,"REF-TEST-NEW");
        assertTrue(bookingDao.isSeatAlreadyBooked(1,40));
        assertThrows(org.springframework.dao.DuplicateKeyException.class,()->bookingDao.saveBooking(realBooking));
        int bookings=db.queryForObject("SELECT COUNT(*) FROM bookings",Integer.class);
        db.update("UPDATE bookings SET booking_status='CANCELLED' WHERE booking_id=1");
        db.update("UPDATE admin_users SET password=? WHERE username='uvin'",encoder.encode("Changed123"));
        seeder.refresh();
        assertEquals(5,db.queryForObject("SELECT COUNT(*) FROM owner_users",Integer.class));
        assertEquals(2,db.queryForObject("SELECT COUNT(*) FROM owner_approval_audit",Integer.class));
        assertEquals(3,db.queryForObject("SELECT COUNT(*) FROM bus_owners",Integer.class));
        assertEquals(1,db.queryForObject("SELECT COUNT(*) FROM owner_users WHERE username='demo_owner_ella' AND approval_status='REJECTED' AND active=FALSE AND password='changed'",Integer.class));
        // Simulate a fresh seed marker with existing accounts: no account is overwritten or approved.
        db.update("DELETE FROM demo_seed_state WHERE seed_key='owner-demo-v1'");
        seeder.refresh();
        assertEquals(2,db.queryForObject("SELECT COUNT(*) FROM owner_approval_audit",Integer.class));
        assertEquals("changed",db.queryForObject("SELECT password FROM owner_users WHERE username='demo_owner_ella'",String.class));
        assertEquals(bookings,db.queryForObject("SELECT COUNT(*) FROM bookings",Integer.class));
        assertEquals("CANCELLED",db.queryForObject("SELECT booking_status FROM bookings WHERE booking_id=1",String.class));
        assertTrue(encoder.matches("Changed123",db.queryForObject("SELECT password FROM admin_users WHERE username='uvin'",String.class)));
        new DemoDataInitializer(db,encoder,tx,Clock.offset(clock,Duration.ofDays(1)),14,"uvin","test-admin-password","test-passenger-password","test-owner-password").refresh();
        assertEquals(2400,db.queryForObject("SELECT COUNT(*) FROM schedules",Integer.class));
        assertEquals(160,db.queryForObject("SELECT COUNT(*) FROM buses",Integer.class));
    }
}
